function hm(tx){var a=document.createElement("article");a.className="chat-message chat-message--host";a.innerHTML='<img class="chat-avatar" src="./assets/avatars/host-mooncat_144.webp" alt="" width="72" height="72"><div class="chat-message__content"><span class="chat-name">NewtNorlly</span><div class="chat-bubble"><p>'+tx+'</p></div></div>';var t=document.getElementById("chatThread");t.append(a);requestAnimationFrame(function(){scrollChat();});}function gm(tx){var a=document.createElement("article");a.className="chat-message chat-message--guest";a.innerHTML='<img class="chat-avatar" src="./assets/avatars/guest-little-deer.webp" alt="" width="42" height="42"><div class="chat-message__content"><span class="chat-name">'+t("guestName")+'</span><div class="chat-bubble"><p>'+tx+'</p></div></div>';var c=document.getElementById("chatThread");c.append(a);requestAnimationFrame(function(){scrollChat();});}
